import type { CarouselFSMEvent, CarouselFSMState, CarouselVisualState } from './Carousel.types';

/**
 * Creates the initial Carousel FSM state
 *
 * @param activeIndex - Initial active slide index
 * @param slideCount - Total number of slides
 * @param autoPlay - Whether autoplay is enabled
 * @returns Initial FSM state
 *
 * @example
 * ```ts
 * const initialState = createInitialCarouselFSMState(0, 5, true);
 * ```
 */
export function createInitialCarouselFSMState(
  activeIndex = 0,
  slideCount = 0,
  autoPlay = false
): CarouselFSMState {
  return {
    visualState: autoPlay ? 'playing' : 'idle',
    activeIndex,
    prevIndex: activeIndex,
    isPlaying: autoPlay,
    isPaused: false,
    isTransitioning: false,
    isDragging: false,
    slideCount,
  };
}

/**
 * Compute next index with optional wrapping
 */
function computeNextIndex(currentIndex: number, slideCount: number, wrap: boolean): number {
  if (slideCount === 0) {
    return 0;
  }
  if (wrap) {
    return (currentIndex + 1) % slideCount;
  }
  return Math.min(currentIndex + 1, slideCount - 1);
}

/**
 * Compute previous index with optional wrapping
 */
function computePrevIndex(currentIndex: number, slideCount: number, wrap: boolean): number {
  if (slideCount === 0) {
    return 0;
  }
  if (wrap) {
    return (currentIndex - 1 + slideCount) % slideCount;
  }
  return Math.max(currentIndex - 1, 0);
}

/**
 * Derive visual state from FSM state
 */
function deriveVisualState(state: CarouselFSMState): CarouselVisualState {
  if (state.isDragging) {
    return 'dragging';
  }
  if (state.isTransitioning) {
    return 'transitioning';
  }
  if (state.isPaused) {
    return 'paused';
  }
  if (state.isPlaying) {
    return 'playing';
  }
  return 'idle';
}

/**
 * Carousel FSM reducer
 *
 * Handles all carousel state transitions including:
 * - Navigation (next, prev, go to specific slide)
 * - Autoplay control (play, pause, toggle)
 * - Transition states
 * - Drag/swipe states
 *
 * @param state - Current FSM state
 * @param event - FSM event to process
 * @param wrap - Whether to wrap around at boundaries (default: true)
 * @returns Updated FSM state
 *
 * @example
 * ```ts
 * const [state, dispatch] = useReducer(
 *   (s, e) => carouselFSMReducer(s, e, true),
 *   undefined,
 *   () => createInitialCarouselFSMState(0, 5, false)
 * );
 * dispatch({ type: 'NEXT' });
 * ```
 */
export function carouselFSMReducer(
  state: CarouselFSMState,
  event: CarouselFSMEvent,
  wrap = true
): CarouselFSMState {
  switch (event.type) {
    case 'NEXT': {
      // Don't navigate while transitioning
      if (state.isTransitioning) {
        return state;
      }

      const nextIndex = computeNextIndex(state.activeIndex, state.slideCount, wrap);
      // If not wrapping and already at end, don't change
      if (nextIndex === state.activeIndex) {
        return state;
      }

      const nextState: CarouselFSMState = {
        ...state,
        prevIndex: state.activeIndex,
        activeIndex: nextIndex,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'PREV': {
      if (state.isTransitioning) {
        return state;
      }

      const prevIndex = computePrevIndex(state.activeIndex, state.slideCount, wrap);
      if (prevIndex === state.activeIndex) {
        return state;
      }

      const nextState: CarouselFSMState = {
        ...state,
        prevIndex: state.activeIndex,
        activeIndex: prevIndex,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'GO_TO': {
      if (state.isTransitioning) {
        return state;
      }

      const targetIndex = event.payload;
      // Validate bounds
      if (targetIndex < 0 || targetIndex >= state.slideCount) {
        return state;
      }
      if (targetIndex === state.activeIndex) {
        return state;
      }

      const nextState: CarouselFSMState = {
        ...state,
        prevIndex: state.activeIndex,
        activeIndex: targetIndex,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'PLAY': {
      const nextState: CarouselFSMState = {
        ...state,
        isPlaying: true,
        isPaused: false,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'PAUSE': {
      const nextState: CarouselFSMState = {
        ...state,
        isPaused: true,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'TOGGLE_PAUSE': {
      const nextState: CarouselFSMState = {
        ...state,
        isPaused: !state.isPaused,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'TRANSITION_START': {
      const nextState: CarouselFSMState = {
        ...state,
        isTransitioning: true,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'TRANSITION_END': {
      const nextState: CarouselFSMState = {
        ...state,
        isTransitioning: false,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'DRAG_START': {
      const nextState: CarouselFSMState = {
        ...state,
        isDragging: true,
        // Pause autoplay while dragging
        isPaused: state.isPlaying ? true : state.isPaused,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'DRAG_END': {
      const nextState: CarouselFSMState = {
        ...state,
        isDragging: false,
        // Resume if was playing before drag
        isPaused: state.isPlaying ? false : state.isPaused,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'SET_SLIDE_COUNT': {
      const newCount = event.payload;
      // Clamp activeIndex if it exceeds new count
      const clampedIndex = newCount > 0 ? Math.min(state.activeIndex, newCount - 1) : 0;

      const nextState: CarouselFSMState = {
        ...state,
        slideCount: newCount,
        activeIndex: clampedIndex,
        prevIndex: clampedIndex,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    case 'RESET_FROM_PROPS': {
      const { activeIndex, slideCount } = event.payload;
      const clampedIndex = slideCount > 0 ? Math.min(activeIndex, slideCount - 1) : 0;

      const nextState: CarouselFSMState = {
        ...state,
        slideCount,
        activeIndex: clampedIndex,
        prevIndex: state.activeIndex !== clampedIndex ? state.activeIndex : state.prevIndex,
      };
      nextState.visualState = deriveVisualState(nextState);
      return nextState;
    }

    default:
      return state;
  }
}

/**
 * Get the visual state attribute value for the carousel
 *
 * @param state - Current FSM state
 * @returns Visual state string for data-visual-state attribute
 */
export function getCarouselVisualState(state: CarouselFSMState): CarouselVisualState {
  return state.visualState;
}

import {
  Children,
  cloneElement,
  forwardRef,
  isValidElement,
  memo,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';

import { cn, mergeRefs } from '../../utils';

import {
  carouselFSMReducer,
  createInitialCarouselFSMState,
  getCarouselVisualState,
} from './Carousel.fsm';
import { CarouselCaption } from './CarouselCaption';
import { CarouselControl } from './CarouselControl';
import { CarouselIndicators } from './CarouselIndicators';
import { CarouselItem } from './CarouselItem';
import { CarouselPauseButton } from './CarouselPauseButton';

import type { CarouselItemProps, CarouselProps } from './Carousel.types';
import type { ReactElement } from 'react';

/**
 * Default autoplay interval in milliseconds
 */
const DEFAULT_INTERVAL = 5000;

/**
 * Default swipe threshold in pixels
 */
const DEFAULT_SWIPE_THRESHOLD = 50;

/**
 * Hook to detect prefers-reduced-motion media query.
 * Returns true when the user prefers reduced motion.
 */
function useReducedMotion(): boolean {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(() => {
    if (typeof window === 'undefined') {
      return false;
    }
    return window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? false;
  });

  useEffect(() => {
    if (typeof window === 'undefined') {
      return undefined;
    }

    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

    const handler = (event: MediaQueryListEvent): void => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', handler);
    return (): void => {
      mediaQuery.removeEventListener('change', handler);
    };
  }, []);

  return prefersReducedMotion;
}

/**
 * Carousel Component
 *
 * A fully accessible carousel for cycling through images or content.
 * Supports autoplay, touch gestures, keyboard navigation, and custom indicators.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - Semantic section element for the carousel container
 * - aria-label for screen reader identification
 * - aria-live="polite" for slide change announcements
 * - Keyboard navigation (Arrow keys)
 * - Pause/Play button for autoplay (required for WCAG)
 * - Each control and indicator properly labeled
 * - Focus management during navigation
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - No dangerouslySetInnerHTML
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * // Basic carousel
 * <Carousel>
 *   <CarouselItem>
 *     <img src="slide1.jpg" alt="First slide" className="d-block w-100" />
 *   </CarouselItem>
 *   <CarouselItem>
 *     <img src="slide2.jpg" alt="Second slide" className="d-block w-100" />
 *   </CarouselItem>
 * </Carousel>
 *
 * // With autoplay and controls
 * <Carousel autoPlay interval={3000} controls indicators>
 *   {slides}
 * </Carousel>
 *
 * // Controlled carousel
 * <Carousel activeIndex={index} onSelect={setIndex}>
 *   {slides}
 * </Carousel>
 * ```
 *
 * @see https://getbootstrap.com/docs/5.3/components/carousel/
 */
const CarouselBase = memo(forwardRef<HTMLDivElement, CarouselProps>(
  (
    {
      children,
      activeIndex: controlledActiveIndex,
      defaultActiveIndex = 0,
      onSelect,
      animation = 'slide',
      autoPlay = false,
      interval = DEFAULT_INTERVAL,
      pauseOnHover = true,
      pauseOnFocus = true,
      keyboard = true,
      touch = true,
      wrap = true,
      controls = true,
      indicators = true,
      dark = false,
      className = '',
      style,
      id,
      'aria-label': ariaLabel = 'Carousel',
      'aria-labelledby': ariaLabelledBy,
      swipeThreshold = DEFAULT_SWIPE_THRESHOLD,
      slideLabels,
      showPauseButton,
      onSlideChanged,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    // Determine if controlled
    const isControlled = controlledActiveIndex !== undefined;

