      keyboard,
      pauseOnHover,
      autoPlay,
      pauseOnFocus,
      touch,
      handleKeyDown,
      handleMouseEnter,
      handleMouseLeave,
      handleFocus,
      handleBlur,
      handleTouchStart,
      handleTouchMove,
      handleTouchEnd,
